class QueryJoinOptimizerExistenceScopeTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void unionScopeAdmissionRetainsScopesForExistsLocalVariables() throws Exception {
		List<Map<String, String>> expected = List.of(
				Map.of("branch", "exists-1", "x", "urn:outside"),
				Map.of("branch", "exists-2", "x", "urn:outside"));
		TupleExpr raw = scopedExistenceUnion();
		List<Map<String, String>> rawResults = evaluate(raw);
		assertThat(rawResults).containsExactlyInAnyOrderElementsOf(expected);

		TupleExpr optimized = scopedExistenceUnion();
		Union originalUnion = findUnion(optimized);
		new UnionScopeChangeOptimizer().optimize(optimized, null, EmptyBindingSet.getInstance());

		List<Filter> filters = filters(originalUnion);
		assertThat(originalUnion.isVariableScopeChange()).as("EXISTS-local x cannot be supplied by a branch sibling")
				.isTrue();
		assertThat(filters).hasSize(2).allMatch(Filter::isVariableScopeChange);
		assertThat(evaluate(optimized)).as("optimized algebra: %s", optimized)
				.containsExactlyInAnyOrderElementsOf(rawResults);
	}

	@Test
	void queryJoinAlonePreservesMarkedExistsInputs() throws Exception {
		List<Map<String, String>> expected = List.of(
				Map.of("branch", "exists-1", "x", "urn:outside"),
				Map.of("branch", "exists-2", "x", "urn:outside"));
		TupleExpr raw = scopedExistenceUnion();
		List<Map<String, String>> rawResults = evaluate(raw);
		assertThat(rawResults).containsExactlyInAnyOrderElementsOf(expected);

		TupleExpr optimized = scopedExistenceUnion();
		Union union = findUnion(optimized);
		new QueryJoinOptimizer(new EvaluationStatistics()).optimize(optimized, null, EmptyBindingSet.getInstance());

		List<Map<String, String>> optimizedResults = evaluate(optimized);
		List<Join> branches = List.of((Join) union.getLeftArg(), (Join) union.getRightArg());
		assertThat(branches).allSatisfy(branch -> assertThat(branch.getLeftArg()).isInstanceOf(Extension.class));
		assertThat(branches).extracting(Join::getAlgorithmName)
				.containsExactly("IndependentJoinIteration", "HashJoinIteration");
		assertThat(filters(union)).hasSize(2).allMatch(Filter::isVariableScopeChange);
		assertThat(optimizedResults).as("QJO-only plan: %s", optimized)
				.containsExactlyInAnyOrderElementsOf(rawResults);
	}

	private static TupleExpr scopedExistenceUnion() {
		Filter existsFilter = new Filter(
				assignment(List.of(binding("branch", VF.createLiteral("exists-1")),
						binding("branch", VF.createLiteral("exists-2")))),
				new Exists(assignment(List.of(binding("x", VF.createIRI("urn:inside"))))));
		existsFilter.setVariableScopeChange(true);

		Filter notExistsFilter = new Filter(
				assignment(List.of(binding("branch", VF.createLiteral("not-exists-1")),
						binding("branch", VF.createLiteral("not-exists-2")))),
				new Not(new Exists(assignment(List.of(binding("x", VF.createIRI("urn:inside")))))));
		notExistsFilter.setVariableScopeChange(true);

		Join existsBranch = new Join(existsFilter,
				new Extension(new SingletonSet(),
						new ExtensionElem(new ValueConstant(VF.createIRI("urn:outside")), "x")));
		Join notExistsBranch = new Join(notExistsFilter,
				new Extension(new SingletonSet(),
						new ExtensionElem(new ValueConstant(VF.createIRI("urn:outside")), "x")));
		Union union = new Union(existsBranch, notExistsBranch);
		union.setVariableScopeChange(true);
		return new QueryRoot(union);
	}

	private static BindingSetAssignment assignment(List<BindingSet> rows) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingSets(rows);
		return assignment;
	}

	private static BindingSet binding(String name, Value value) {
		return new ListBindingSet(List.of(name), value);
	}

	private static Union findUnion(TupleExpr expression) {
		List<Union> unions = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (node instanceof Union union) {
					unions.add(union);
				}
				super.meetNode(node);
			}
		});
		assertThat(unions).hasSize(1);
		return unions.getFirst();
	}

	private static List<Filter> filters(Union union) {
		List<Filter> filters = new ArrayList<>();
		union.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Filter filter) {
				filters.add(filter);
				super.meet(filter);
			}
		});
		return filters;
	}

	private static List<Map<String, String>> evaluate(TupleExpr expression) throws Exception {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		List<Map<String, String>> results = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = strategy.evaluate(expression, EmptyBindingSet.getInstance())) {
			while (iteration.hasNext()) {
				BindingSet bindingSet = iteration.next();
				Map<String, String> result = new HashMap<>();
				for (String name : bindingSet.getBindingNames()) {
					result.put(name, bindingSet.getValue(name).stringValue());
				}
				results.add(Map.copyOf(result));
			}
		}
		return results;
	}
}
